sql.if:
AND (
	SELECT COUNT(*)
	FROM voj_discussion_reply_votes v
	JOIN voj_discussion_replies r ON v.discussion_reply_id = r.discussion_reply_id
	WHERE r.discussion_thread_id = dt.discussion_thread_id AND v.vote_type = 2
) < #{reportHideThreshold}

mapper.select:
SELECT *, ( SELECT COUNT(*) FROM voj_discussion_replies dr WHERE dt.discussion_thread_id = dr.discussion_thread_id ) AS discussion_replies, ( SELECT COUNT(*) FROM voj_discussion_reply_votes v JOIN voj_discussion_replies r ON v.discussion_reply_id = r.discussion_reply_id WHERE r.discussion_thread_id = dt.discussion_thread_id AND v.vote_type = 2 ) AS discussion_reports, (
SELECT discussion_reply_id FROM voj_discussion_replies dr WHERE dt.discussion_thread_id = dr.discussion_thread_id
AND dr.discussion_reply_visible = 1
ORDER BY discussion_reply_id DESC LIMIT 1 ) AS latest_discussion_reply_id FROM voj_discussion_threads dt
AND problem_id = #{problemId}
AND discussion_topic_id = #{discussionTopicId}
ORDER BY discussion_thread_pinned DESC, latest_discussion_reply_id DESC LIMIT #{offset}, #{limit}

mapper.update:
UPDATE voj_discussion_threads
SET discussion_thread_creator_uid = #{discussionThreadCreator.uid}, discussion_thread_create_time = #{discussionThreadCreateTime}, problem_id = #{problem.problemId}, discussion_topic_id = #{discussionTopic.discussionTopicId}, discussion_thread_name = #{discussionThreadTitle}, discussion_thread_visible = #{visible}, discussion_thread_pinned = #{pinned}, discussion_thread_locked = #{locked}
WHERE discussion_thread_id = #{discussionThreadId}

UPDATE voj_discussion_threads
SET discussion_thread_visible = #{visible}
WHERE discussion_thread_id = #{discussionThreadId}

UPDATE voj_discussion_threads
SET discussion_thread_name = #{discussionThreadTitle}, discussion_topic_id = #{discussionTopic.discussionTopicId}, discussion_thread_visible = #{visible}, discussion_thread_pinned = #{pinned}, discussion_thread_locked = #{locked}
WHERE discussion_thread_id = #{discussionThreadId}
